(()=>{"use strict";function vehiculoCtrl($scope,$http,_modalSvc,_nombreModal){$scope.data={},$scope.openModal=async item=>{const{vehiculo:vehiculo}=_nombreModal,{ModalVehiculoCtrl:ModalVehiculoCtrl}=await import("./../../modal/"+vehiculo.MODAL_CTRL),modalRef=_modalSvc.openModalSecond(ModalVehiculoCtrl,"Vehiculo/"+vehiculo.MODAL_CSHTML,"md",item);modalRef.result.then(result=>{"object"==typeof result&&$scope.getVehiculos()})},$scope.getVehiculos=function(){showLoader(),$http.get("/Vehiculo/Get").then(({data:response})=>{if("0"===response.id)return hideLoader(),void toastr.warning(response.message);$scope.vehiculos=response.data,hideLoader()}).catch(error=>{hideLoader(),toastr.error(error)})},$scope.getVehiculos(),$scope.sweetAlertEliminar=async item=>{let{isConfirmed:isConfirmed}=await Swal.fire({icon:"warning",html:"<small>Esta seguro de eliminar este registro ahora?</small>",showConfirmButton:!0,confirmButtonText:"Si, eliminar",showCancelButton:!0,cancelButtonText:"No, cancelar!",allowOutsideClick:!1});isConfirmed&&$http.post("/Vehiculo/Delete?id="+item.idVehiculo).then(({data:response})=>{"0"!==response.id?"1"===response.id&&($scope.getVehiculos(),toastr.success(response.message)):toastr.warning(response.message)})}}angular.module("acontPlusApp").controller("vehiculoCtrl",vehiculoCtrl),vehiculoCtrl.$inject=["$scope","$http","modalService","nombreModal"]})(window.angular);